R["hsg-p2-day-sim"] = "#include <iostream>\nvoid solve(std::istream& in, std::ostream& out) {\n    long long g, h, T; in >> g >> h >> T;\n    long long height = 1;\n    for (long long day = 1; day <= 1000000; ++day) {\n        height += g;\n        if (height > T) { out << day << \"\\n\"; return; }\n        if (h > 0 && height > h) height = h;   // h = 0 means no mower\n    }\n    out << -1 << \"\\n\";\n}";
W["hsg-p2-day-sim"] = "#include <iostream>\nvoid solve(std::istream& in, std::ostream& out) {\n    long long g, h, T; in >> g >> h >> T;\n    long long height = 1;\n    // near-miss: compares against T AFTER the mower cut, so a day that\n    // crossed T but got cut back is never reported\n    for (long long day = 1; day <= 1000000; ++day) {\n        height += g;\n        if (h > 0 && height > h) height = h;\n        if (height > T) { out << day << \"\\n\"; return; }\n    }\n    out << -1 << \"\\n\";\n}";
