R["hsg-p4-multiset-eq"] = "#include <iostream>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    const int MAXV = 100000;\n    vector<int> f(MAXV + 1, 0);\n    for (int i = 0; i < n; ++i) { int x; in >> x; ++f[x]; }\n    for (int i = 0; i < m; ++i) { int x; in >> x; --f[x]; }\n    for (int v = 0; v <= MAXV; ++v) {\n        if (f[v] != 0) { out << \"DIFF\\n\"; return; }\n    }\n    out << \"SAME\\n\";\n}";
W["hsg-p4-multiset-eq"] = "#include <iostream>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    const int MAXV = 100000;\n    vector<int> f(MAXV + 1, 0);\n    for (int i = 0; i < n; ++i) { int x; in >> x; ++f[x]; }\n    // near-miss: never checks that bag sizes match \u2014 a leftover count\n    // from the longer bag goes unnoticed\n    for (int i = 0; i < m; ++i) { int x; in >> x; --f[x]; }\n    for (int v = 0; v <= MAXV; ++v) {\n        if (f[v] > 0) { out << \"DIFF\\n\"; return; }\n    }\n    out << \"SAME\\n\";\n}";
R["hsg-p4-pair-sum"] = "#include <iostream>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long k; in >> n >> k;\n    const int MAXV = 1000000;\n    vector<long long> cnt(MAXV + 1, 0);\n    long long pairs = 0;\n    for (int i = 0; i < n; ++i) {\n        long long x; in >> x;\n        long long need = k - x;\n        if (need >= 0 && need <= MAXV) pairs += cnt[need];\n        ++cnt[x];\n    }\n    out << pairs << \"\\n\";\n}";
