R["hsg-p5-meetings"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long, long long>> v(n);\n    for (auto& p : v) in >> p.second >> p.first;   // store (end, start)\n    sort(v.begin(), v.end());\n    int cnt = 0;\n    long long lastEnd = -1;\n    for (auto& p : v) {\n        if (p.second >= lastEnd) { ++cnt; lastEnd = p.first; }\n    }\n    out << cnt << \"\\n\";\n}";
W["hsg-p5-meetings"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long, long long>> v(n);\n    for (auto& p : v) in >> p.first >> p.second;   // (start, end)\n    // near-miss: sorts by START time \u2014 a long early meeting blocks many\n    // short later ones\n    sort(v.begin(), v.end());\n    int cnt = 0;\n    long long lastEnd = -1;\n    for (auto& p : v) {\n        if (p.first >= lastEnd) { ++cnt; lastEnd = p.second; }\n    }\n    out << cnt << \"\\n\";\n}";
R["hsg-p5-waiting"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> t(n);\n    for (long long& x : t) in >> x;\n    sort(t.begin(), t.end());\n    long long total = 0, elapsed = 0;\n    for (int i = 0; i < n; ++i) {\n        total += elapsed;   // everyone before i has finished\n        elapsed += t[i];\n    }\n    out << total << \"\\n\";\n}";
W["hsg-p5-waiting"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> t(n);\n    for (long long& x : t) in >> x;\n    // near-miss: sorts DESCENDING \u2014 the longest jobs first, the exact\n    // opposite of the shortest-processing-time rule\n    sort(t.rbegin(), t.rend());\n    long long total = 0, elapsed = 0;\n    for (int i = 0; i < n; ++i) {\n        total += elapsed;\n        elapsed += t[i];\n    }\n    out << total << \"\\n\";\n}";
R["hsg-p5-cover"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long, long long>> v(n);\n    for (auto& p : v) in >> p.first >> p.second;\n    // Sweep endpoints: at a start, coverage +1; just after an end, -1.\n    // The best point sits at some interval's start (closed intervals).\n    vector<pair<long long, int>> ev;\n    for (auto& p : v) { ev.push_back({p.first, +1}); ev.push_back({p.second + 1, -1}); }\n    sort(ev.begin(), ev.begin() + 0); // placeholder replaced below\n    sort(ev.begin(), ev.end());\n    int cur = 0, best = 0;\n    for (auto& e : ev) {\n        cur += e.second;\n        if (e.second == +1) best = max(best, cur);\n    }\n    out << best << \"\\n\";\n}";
W["hsg-p5-cover"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long, long long>> v(n);\n    for (auto& p : v) in >> p.first >> p.second;\n    vector<pair<long long, int>> ev;\n    for (auto& p : v) { ev.push_back({p.first, +1}); ev.push_back({p.second, -1}); }\n    sort(ev.begin(), ev.end());\n    // near-miss: treats the end as exclusive (interval [s, e) not [s, e]),\n    // so intervals that merely touch at one point count as disjoint\n    int cur = 0, best = 0;\n    for (auto& e : ev) {\n        cur += e.second;\n        if (e.second == +1) best = max(best, cur);\n    }\n    out << best << \"\\n\";\n}";
