W["hsg-cp-m5-tents"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    // near-miss: greedy takes every locally-large value while checking\n    // only the immediate previous pick, missing better combos like\n    // 3 2 5 10 \u2192 takes 3, skips 2, takes 5, then 10 is adjacent to 5 \u2192\n    // total 8 < 13\n    long long total = 0;\n    int prevPicked = -2;\n    for (int i = 0; i < n; ++i) {\n        long long x; in >> x;\n        if (x > 0 && i - prevPicked > 1) { total += x; prevPicked = i; }\n    }\n    out << total << \"\\n\";\n}";
R["hsg-p6-min-diff"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (long long& x : a) in >> x;\n    sort(a.begin(), a.end());\n    long long best = a[1] - a[0];\n    for (int i = 2; i < n; ++i) best = min(best, a[i] - a[i-1]);\n    out << best << \"\\n\";\n}";
W["hsg-p6-min-diff"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (long long& x : a) in >> x;\n    sort(a.begin(), a.end());\n    // near-miss: initializes the running best to 0 \u2014 with an all-negative\n    // or all-distinct-positive input the true min can never beat 0, so the\n    // answer is wrong (also fails duplicates-are-0 only by luck)\n    long long best = 0;\n    for (int i = 1; i < n; ++i) best = min(best, a[i] - a[i-1]);\n    out << best << \"\\n\";\n}";
R["hsg-p6-desc-median"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (long long& x : a) in >> x;\n    vector<long long> asc = a;\n    sort(asc.begin(), asc.end());\n    sort(a.begin(), a.end(), greater<long long>());\n    for (int i = 0; i < n; ++i) out << a[i] << \" \";\n    out << \"\\n\";\n    out << asc[(n - 1) / 2] << \"\\n\";\n}";
W["hsg-p6-desc-median"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (long long& x : a) in >> x;\n    sort(a.begin(), a.end(), greater<long long>());\n    for (int i = 0; i < n; ++i) out << a[i] << \" \";\n    out << \"\\n\";\n    // near-miss: picks the UPPER middle for even n (n/2 instead of (n-1)/2)\n    out << a[n / 2] << \"\\n\";\n}";
R["hsg-p6-merge-intervals"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long,long long>> iv(n);\n    for (auto& p : iv) in >> p.first >> p.second;\n    sort(iv.begin(), iv.end());\n    vector<pair<long long,long long>> merged;\n    for (auto& p : iv) {\n        if (!merged.empty() && p.first <= merged.back().second)\n            merged.back().second = max(merged.back().second, p.second);\n        else merged.push_back(p);\n    }\n    for (auto& p : merged) out << p.first << \" \" << p.second << \"\\n\";\n}";
W["hsg-p6-merge-intervals"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long,long long>> iv(n);\n    for (auto& p : iv) in >> p.first >> p.second;\n    sort(iv.begin(), iv.end());\n    vector<pair<long long,long long>> merged;\n    for (auto& p : iv) {\n        // near-miss: '<' instead of '<=' \u2014 touching intervals (end ==\n        // next start) stay separate, violating the merge contract\n        if (!merged.empty() && p.first < merged.back().second)\n            merged.back().second = max(merged.back().second, p.second);\n        else merged.push_back(p);\n    }\n    for (auto& p : merged) out << p.first << \" \" << p.second << \"\\n\";\n}";
