R["hsg-cp-m6-tower"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> h(n);\n    for (long long& x : h) in >> x;\n    sort(h.begin(), h.end());\n    // candidates: lower median and upper median \u2014 evaluate both\n    long long m1 = h[(n - 1) / 2], m2 = h[n / 2];\n    auto cost = [&](long long t) {\n        long long c = 0;\n        for (long long x : h) c += llabs(x - t);\n        return c;\n    };\n    long long c1 = cost(m1), c2 = cost(m2);\n    // smallest optimal height: for odd n it is m1; for even n any point\n    // in [m1, m2] ties \u2014 m1 is the smallest, and its cost equals c2\n    long long bestH = m1, bestC = c1;\n    if (c2 < bestC) { bestC = c2; bestH = m2; }\n    out << bestC << \"\\n\" << bestH << \"\\n\";\n}";
W["hsg-cp-m6-tower"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> h(n);\n    for (long long& x : h) in >> x;\n    sort(h.begin(), h.end());\n    // near-miss: minimizes around the MEAN \u2014 the mean minimizes squared\n    // error, not sum of absolute differences; fails skewed inputs\n    long long sum = 0;\n    for (long long x : h) sum += x;\n    long long t = sum / n;\n    long long c = 0;\n    for (long long x : h) c += llabs(x - t);\n    out << c << \"\\n\" << t << \"\\n\";\n}";
