R["hsg-cp-m7-climb"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long k; in >> n >> k;\n    vector<long long> h(n);\n    for (long long& x : h) in >> x;\n    // feasible(d): keep every up-step <= d using k planks; a gap with\n    // up-step u needs max(0, u - d) planks\n    auto feasible = [&](long long d) {\n        long long need = 0;\n        for (int i = 1; i < n; ++i)\n            if (h[i] - h[i-1] > d) need += h[i] - h[i-1] - d;\n        return need <= k;\n    };\n    long long lo = 0, hi = 0;\n    for (int i = 1; i < n; ++i) hi = max(hi, h[i] - h[i-1]);\n    while (lo < hi) {\n        long long mid = lo + (hi - lo) / 2;\n        if (feasible(mid)) hi = mid; else lo = mid + 1;\n    }\n    out << lo << \"\\n\";\n}";
W["hsg-cp-m7-climb"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long k; in >> n >> k;\n    vector<long long> h(n);\n    for (long long& x : h) in >> x;\n    // near-miss: counts how many GAPS exceed d, not how many PLANKS\n    // are needed \u2014 a gap 5 above the limit needs 5 planks, not 1,\n    // so this undercounts and accepts too-large d\n    auto feasible = [&](long long d) {\n        long long bad = 0;\n        for (int i = 1; i < n; ++i)\n            if (h[i] - h[i-1] > d) ++bad;\n        return bad <= k;\n    };\n    long long lo = 0, hi = 0;\n    for (int i = 1; i < n; ++i) hi = max(hi, h[i] - h[i-1]);\n    while (lo < hi) {\n        long long mid = lo + (hi - lo) / 2;\n        if (feasible(mid)) hi = mid; else lo = mid + 1;\n    }\n    out << lo << \"\\n\";\n}";
